import{_ as l,r as e,o as i,c as r,e as p,a as n,s as t,d as s}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"错误和日志 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置","slug":"配置","link":"#配置","children":[{"level":4,"title":"错误详情","slug":"错误详情","link":"#错误详情","children":[]},{"level":4,"title":"日志文件模式","slug":"日志文件模式","link":"#日志文件模式","children":[]}]},{"level":2,"title":"可用的异常","slug":"可用的异常","link":"#可用的异常","children":[{"level":3,"title":"应用程序异常","slug":"应用程序异常","link":"#应用程序异常","children":[]},{"level":3,"title":"系统异常","slug":"系统异常","link":"#系统异常","children":[]},{"level":3,"title":"未找到异常","slug":"未找到异常","link":"#未找到异常","children":[]},{"level":3,"title":"验证异常","slug":"验证异常","link":"#验证异常","children":[]},{"level":3,"title":"AJAX 异常","slug":"ajax-异常","link":"#ajax-异常","children":[]}]},{"level":2,"title":"异常处理","slug":"异常处理","link":"#异常处理","children":[{"level":3,"title":"错误处理程序的放置位置","slug":"错误处理程序的放置位置","link":"#错误处理程序的放置位置","children":[]}]},{"level":2,"title":"HTTP 异常","slug":"http-异常","link":"#http-异常","children":[{"level":3,"title":"自定义错误页面","slug":"自定义错误页面","link":"#自定义错误页面","children":[]}]},{"level":2,"title":"日志记录","slug":"日志记录","link":"#日志记录","children":[{"level":4,"title":"上下文信息","slug":"上下文信息","link":"#上下文信息","children":[]},{"level":3,"title":"助手函数","slug":"助手函数","link":"#助手函数","children":[]}]}],"relativePath":"2.x/zh-cn/services/error-log.md","filePath":"2.x/zh-cn/services/error-log.md"}'),u={name:"2.x/zh-cn/services/error-log.md"};function k(d,a,g,h,v,x){const o=e("pre-heading"),c=e("post-heading");return i(),r("div",null,[p(o),a[0]||(a[0]=n("h1",null,"错误和日志",-1)),p(c),a[1]||(a[1]=t(`<p>当您第一次开始使用October CMS时，已经为您配置了错误和异常处理。 可以通过两种方式访问事件日志：</p><p>1.打开文件<code>storage/logs/system.log</code>可以在文件系统中查看事件日志。</p><ol><li>或者，可以通过管理区域导航到 <em>System[设置] &gt; Logs[日志] &gt; Event Log[事件日志]</em> 来查看它。</li></ol><p>当显示错误页面和某些 <a href="#oc-exception-types">异常类型</a> 时，始终会创建日志条目。</p><h2 id="配置"><a href="#配置" class="header-anchor">#</a> 配置</h2><h4 id="错误详情"><a href="#错误详情" class="header-anchor">#</a> 错误详情</h4><p>您的应用程序通过浏览器显示的错误详细信息的数量由 <code>config/app.php</code> 配置文件中的 <code>debug</code> 配置选项控制。 默认情况下，详细的错误报告是<em>打开</em>的，因此查看详细的错误信息对调试和解决问题很有帮助。 关闭此功能后，当页面出现问题时，将显示一般错误消息。</p><p>对于本地开发，您应该将 <code>debug</code> 值设置为 <code>true</code>。 在您的生产环境中，此值应始终为 <code>false</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/*
|--------------------------------------------------------------------------
| Application Debug Mode[应用程序调试模式]
|--------------------------------------------------------------------------
|
| When your application is in debug mode, detailed error messages with
| stack traces will be shown on every error that occurs within your
| application. If disabled, a simple generic error page is shown.
|
*/</span>

<span class="token string single-quoted-string">&#39;debug&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
</code></pre></div><h4 id="日志文件模式"><a href="#日志文件模式" class="header-anchor">#</a> 日志文件模式</h4><p>October 支持 <code>single</code>、<code>daily</code>、<code>syslog</code> 和 <code>errorlog</code> 日志记录模式。 例如，如果您希望使用每日日志文件而不是单个文件，您只需在 <code>config/app.php</code> 配置文件中设置 <code>log</code> 值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;log&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;daily&#39;</span>
</code></pre></div><p><a id="oc-exception-types"></a></p><h2 id="可用的异常"><a href="#可用的异常" class="header-anchor">#</a> 可用的异常</h2><p>October CMS 提供了几种预置好的基本异常类型。</p><h3 id="应用程序异常"><a href="#应用程序异常" class="header-anchor">#</a> 应用程序异常</h3><p><code>October\\Rain\\Exception\\ApplicationException</code> 类，别名为 <code>ApplicationException</code>，是在简单应用条件失败时使用的最常见异常类型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;你必须先登录才能做到这一点！&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>错误消息将被简化，并且永远不会包含任何敏感信息，如 PHP 文件和行号。</p><h3 id="系统异常"><a href="#系统异常" class="header-anchor">#</a> 系统异常</h3><p><code>October\\Rain\\Exception\\SystemException</code> 类，别名为 <code>SystemException</code>，用于对系统运行至关重要的错误并始终记录在案。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">SystemException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;无法联系邮件服务器 API&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>抛出此异常时，会显示详细的错误消息，其中包含发生该异常的文件和行号。</p><h3 id="未找到异常"><a href="#未找到异常" class="header-anchor">#</a> 未找到异常</h3><p><code>October\\Rain\\Exception\\NotFoundException</code> 类，别名为 <code>NotFoundException</code>，用于在遇到缺失记录时发生的错误。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;记录不存在&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当抛出此异常时，标准响应将更改为显示最近的未找到页面，并添加了 404 状态代码。</p><p><a id="oc-validation-exception"></a></p><h3 id="验证异常"><a href="#验证异常" class="header-anchor">#</a> 验证异常</h3><p><code>October\\Rain\\Exception\\ValidationException</code> 类，别名为 <code>ValidationException</code>，用于与表单提交和无效字段直接相关的错误。 该消息应包含一个包含字段和错误消息的数组。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;对不起，该用户名已被使用！&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以传递 <a href="./validation.html">验证服务</a> 的实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$validation</span> <span class="token operator">=</span> <span class="token class-name static-context">Validator</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token operator">-&gt;</span><span class="token function">fails</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当抛出此异常时，<a href="./../ajax/introduction.html">AJAX 框架</a> 将以可用格式提供此信息并聚焦第一个无效字段。</p><p><a id="oc-ajax-exception"></a></p><h3 id="ajax-异常"><a href="#ajax-异常" class="header-anchor">#</a> AJAX 异常</h3><p><code>October\\Rain\\Exception\\AjaxException</code> 类，别名为 <code>AjaxException</code>，被认为是&quot;智能错误&quot;，将返回 HTTP 代码 406。这允许它们像成功响应一样传递响应内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#flashMessages&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当抛出此异常时，<a href="./../ajax/introduction.html">AJAX 框架</a> 将遵循标准错误工作流程，但也会刷新指定的部件。</p><h2 id="异常处理"><a href="#异常处理" class="header-anchor">#</a> 异常处理</h2><p>所有异常都由 <code>October\\Rain\\Foundation\\Exception\\Handler</code> 类处理。 此类包含两个方法：<code>report</code> 和 <code>render</code>，它们指示是否应记录错误以及如何响应错误。</p><p>但是，如果需要，您可以使用 <code>App::error</code> 方法指定自定义处理程序。 处理程序是根据它们处理的异常的类型提示来调用的。 例如，您可以创建一个只处理 <code>RuntimeException</code> 实例的处理程序：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">RuntimeException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 处理异常...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果异常处理程序返回响应，则该响应将被发送到浏览器，并且不会调用其他错误处理程序：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">InvalidUserException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;对不起！ 此帐户有问题！&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要侦听 PHP 致命错误，您可以使用 <code>App::fatal</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">fatal</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果您有多个异常处理程序，则应按从最通用到最具体的顺序定义它们。因此，例如，处理<code>Exception</code>类型的所有异常处理程序应该在自定义异常类型(如<code>SystemException</code>)之前定义。</p><h3 id="错误处理程序的放置位置"><a href="#错误处理程序的放置位置" class="header-anchor">#</a> 错误处理程序的放置位置</h3><p>错误处理程序注册，如 <a href="./events.html">事件处理程序</a>，通常属于<code>引导代码</code>类别。换句话说，它们让你的应用程序准备好实际处理请求，并且通常需要在实际调用路由或控制器之前执行。最常见的地方是<a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a>的<code>boot</code>方法。或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用它来注册错误处理程序。</p><h2 id="http-异常"><a href="#http-异常" class="header-anchor">#</a> HTTP 异常</h2><p>一些例外情况描述了来自服务器的 HTTP 错误代码。例如，这可能是<code>找不到页面错误(404)</code>、<code>未经授权的错误(401)</code> 甚至是开发人员生成的 500 错误。为了从应用程序中的任何位置生成这样的响应，请使用以下命令：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>abort</code> 方法将立即引发一个异常，该异常将由异常处理程序呈现。 或者，您可以提供响应文本：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;未经授权的行为。&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>该方法可以在请求生命周期的任何时候使用。还有一个<a href="./../markup/function-abort.html">用于中止请求的 Twig 过滤器</a>.</p><h3 id="自定义错误页面"><a href="#自定义错误页面" class="header-anchor">#</a> 自定义错误页面</h3><p>默认情况下，任何错误都会显示一个详细的错误页面，其中包含发生错误的文件内容、行号和堆栈跟踪。 您可以通过在 <code>config/app.php</code> 脚本中将配置值 <code>debug</code> 设置为 <strong>false</strong> 并使用 URL <code>/error</code> 创建一个页面来显示自定义错误页面。</p><h2 id="日志记录"><a href="#日志记录" class="header-anchor">#</a> 日志记录</h2><p>默认情况下，October 配置为为您的应用程序创建一个日志文件，该文件存储在 <code>storage/logs</code> 目录中。 您可以使用 <code>Log</code> 门面将信息写入日志：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;显示用户的用户资料: &#39;</span><span class="token operator">.</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,61)),a[2]||(a[2]=n("p",null,[s("记录器提供 "),n("a",{href:"https://datatracker.ietf.org/doc/html/rfc5424",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("RFC 5424"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(" 中定义的八个记录级别： "),n("strong",null,"emergency"),s(", "),n("strong",null,"alert"),s(", "),n("strong",null,"critical"),s(", "),n("strong",null,"error"),s(", "),n("strong",null,"warning"),s(", "),n("strong",null,"notice"),s(", "),n("strong",null,"info"),s(" 和 "),n("strong",null,"debug"),s("。")],-1)),a[3]||(a[3]=t(`<div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">emergency</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">alert</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">critical</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">warning</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">notice</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">debug</span><span class="token punctuation">(</span><span class="token variable">$error</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="上下文信息"><a href="#上下文信息" class="header-anchor">#</a> 上下文信息</h4><p>一组上下文数据也可以传递给日志方法。 此上下文数据将被格式化并与日志消息一起显示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Log</span><span class="token operator">::</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;用户登录失败。&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-helper-functions"></a></p><h3 id="助手函数"><a href="#助手函数" class="header-anchor">#</a> 助手函数</h3><p>有一些全局助手方法可用于简化日志记录。 <code>trace_log</code> 函数是 <code>Log::info</code> 的别名，支持使用数组和异常作为消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 写入字符串值</span>
<span class="token variable">$val</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world&#39;</span><span class="token punctuation">;</span>
<span class="token function">trace_log</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;值为 &#39;</span><span class="token operator">.</span><span class="token variable">$val</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 转储一个数组值</span>
<span class="token variable">$val</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Some&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;array&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token function">trace_log</span><span class="token punctuation">(</span><span class="token variable">$val</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 跟踪异常</span>
<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
<span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">trace_log</span><span class="token punctuation">(</span><span class="token variable">$ex</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>trace_sql</code> 函数启用数据库日志记录，调用时它将记录发送到数据库的每个命令。 这些记录仅出现在 <code>system.log</code> 文件中，不会出现在管理区域日志中，因为它存储在数据库中，会导致反馈循环。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token function">trace_sql</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 从用户中选择 count(*) 作为聚合</span>
</code></pre></div>`,10))])}const b=l(u,[["render",k]]);export{f as __pageData,b as default};
